import json,glob,os
for f in glob.glob('factors/*.json'):
 if f.endswith('factor_ensemble.json'): continue
 try:
  d=json.load(open(f))
  print(os.path.basename(f), d.get('status'), d.get('daily_ic',d.get('metrics',{}).get('daily_ic')), d.get('daily_icir',d.get('metrics',{}).get('daily_icir')), d.get('factor_name',d.get('name')))
 except Exception as e: print('ERR',f,e)
PY

