from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_account_dict, get_stock_daily_data, get_index_daily_data, rebalance_to_weights

ASSETS = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
last_date = None

def rank_cross(x):
    good = sorted((s, v) for s, v in x.items() if np.isfinite(v))
    out = {s: 0.5 for s in ASSETS}
    for i, (s, _) in enumerate(good): out[s] = (i + 1.0) / len(good)
    return out

def bounded(raw):
    w = {s: max(0., float(raw.get(s, 0))) for s in ASSETS}
    for _ in range(30):
        z = sum(w.values()) or 1.; w = {s: v/z for s,v in w.items()}
        fixed = {s: min(.16, max(.015, w[s])) for s in ASSETS if w[s] < .015 or w[s] > .16}
        if not fixed: break
        free = [s for s in ASSETS if s not in fixed]; rem = 1-sum(fixed.values())
        fz = sum(w[s] for s in free) or 1.
        w = {s: fixed.get(s, w[s]*rem/fz) for s in ASSETS}
    z = sum(w.values()) or 1.; return {s:v/z for s,v in w.items()}

def vix_stress():
    d = get_index_daily_data(symbol="VIX", days=90)
    if d is None or len(d) < 22: return 0.
    c = np.asarray(d.sort_values("date")["close"], float)
    return float(np.clip(c[-1]/max(np.median(c[-22:-1]),1e-9)-1, -.5, 1.5))

@register_hook
def strategy():
    global last_date
    try: selected = json.loads(ENSEMBLE.read_text())["selected_factors"][:10]
    except Exception: return
    if not selected or abs(sum(float(f["weight"]) for f in selected)-1) > 1e-6: return
    ids = [str(f["factor_id"]) for f in selected]
    weights = {str(f["factor_id"]): float(f["weight"]) for f in selected}
    dirs = {str(f["factor_id"]): int(f.get("direction",1)) for f in selected}
    account = get_account_dict()
    if set(account.get("watch_list",[])) != set(ASSETS): return
    data = {}
    for s in ASSETS:
        d = get_stock_daily_data(symbol=s, days=180)
        if d is None or len(d) < 65: return
        d = d.sort_values("date")
        data[s] = {k:np.asarray(d[k],float) for k in ("open","close","high","low")}; data[s]["date"] = str(d.iloc[-1]["date"])
    dt = max(data[s]["date"] for s in ASSETS)
    if last_date is not None:
        try:
            if dt == last_date or np.busday_count(np.datetime64(last_date),np.datetime64(dt)) < 10: return
        except Exception: return
    ret = {n:{s:data[s]["close"][-1]/max(data[s]["close"][-n-1],1e-12)-1 for s in ASSETS} for n in (1,3,5)}
    med5 = float(np.median(list(ret[5].values()))); breadth = sum(v<0 for v in ret[3].values())/15.; stress = vix_stress()
    vol = {}
    for s in ASSETS:
        c=data[s]["close"]; rr=np.diff(c)/np.maximum(c[:-1],1e-12); vol[s]=max(float(np.std(rr[-20:])),.008)
    medvol=float(np.median(list(vol.values()))); sig={fid:{} for fid in ids}
    for s in ASSETS:
        o,c,h,l=(data[s][k] for k in ("open","close","high","low")); one=ret[1][s]
        q={"miner_1_20260716_peer_median_leadlag_5d":ret[5][s]-med5,"miner_2_20260716_risk_adjusted_momentum_20d":(c[-1]/max(c[-21],1e-12)-1)/vol[s],"miner_2_20270506_vix_regime_reversal_1d":-one*(1+max(stress,0)),"miner_1_20280309_beta_neutral_reversal_5d":-(ret[5][s]-med5),"miner_2_20270617_breadth_conditioned_reversal_1d":-one*(1+.5*max(breadth-.5,0)),"miner_3_20260716_clv_1d":(2*c[-1]-h[-1]-l[-1])/max(h[-1]-l[-1],1e-12),"miner_1_20270520_overnight_gap_reversal_1d":-(o[-1]/max(c[-2],1e-12)-1),"reversal_5d_crossasset_20280601":-(ret[5][s]-med5)}
        for fid in ids: sig[fid][s]=dirs[fid]*q.get(fid,0.)
    score={s:.5 for s in ASSETS}
    for fid in ids:
        r=rank_cross(sig[fid])
        for s in ASSETS: score[s]+=weights[fid]*(r[s]-.5)
    raw={s:max(.02,score[s])/(.85+.15*vol[s]/max(medvol,1e-12)) for s in ASSETS}
    if stress>.25 or breadth>=.6 or ret[1]["SPX"]<0:
        for s in ("XAU","US10Y","CN10Y"): raw[s]*=1.5
        for s in ("BTC","ETH","WTI","SOX","NDX"): raw[s]*=.6
    target=bounded(raw); mean=float(np.mean(list(score.values()))); sd=max(float(np.std(list(score.values()))),1e-9)
    forecast={s:float(.01*(score[s]-mean)/sd) for s in ASSETS}
    rebalance_to_weights(target,forecast_returns=forecast,factor_ids=ids,horizon_days=10); last_date=dt
"}

